 * {
   margin: 0;
   padding: 0;
   box-sizing: border-box;
 }

 :root {
   color-scheme: dark;
   --bg-primary: #0f0f0f;
   --bg-secondary: #1a1a1a;
   --bg-tertiary: #2d2d2d;
   --text-primary: #ffffff;
   --text-secondary: #b0b0b0;
   --border-color: #3a3a3a;
   --accent: #4a9eff;
   --accent-hover: #357abd;
   --danger: #ff6b6b;
   --danger-hover: #ff5252;
   --success: #51cf66;
   --focus-ring: #4a9eff;
 }

 body {
   background-color: var(--bg-primary);
   color: var(--text-primary);
   font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
   font-size: 16px;
   line-height: 1.6;
   min-height: 100vh;
   padding: 2rem 1rem;
 }

 main {
   max-width: 1200px;
   margin: 0 auto;
 }

 .image-library h1 {
   font-size: 2.5rem;
   font-weight: 700;
   margin-bottom: 2rem;
   text-align: center;
 }

 .gallery {
   display: grid;
   grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
   gap: 2rem;
 }

 .image-card {
   background: var(--bg-secondary);
   border: 1px solid var(--border-color);
   border-radius: 8px;
   overflow: hidden;
   transition: all 0.2s ease;
 }

 .image-card:hover {
   border-color: var(--accent);
   box-shadow: 0 8px 16px rgba(74, 158, 255, 0.1);
 }

 .image-placeholder {
   width: 100%;
   aspect-ratio: 1;
   background: var(--bg-tertiary);
   display: flex;
   align-items: center;
   justify-content: center;
 }

 .image-placeholder svg {
   width: 80%;
   height: 80%;
 }

 .image-info {
   padding: 1.5rem;
 }

 .image-info h2 {
   font-size: 1.1rem;
   font-weight: 600;
   margin-bottom: 0.5rem;
   color: var(--text-primary);
 }

 .image-date {
   font-size: 0.9rem;
   color: var(--text-secondary);
   margin-bottom: 1rem;
 }

 /* Buttons */
 button {
   font-family: inherit;
   cursor: pointer;
   border: none;
   border-radius: 6px;
   font-size: 0.95rem;
   font-weight: 500;
   transition: all 0.2s ease;
   padding: 0.75rem 1rem;
 }

 button:focus-visible {
   outline: 2px solid var(--focus-ring);
   outline-offset: 2px;
 }

 button:active {
   transform: scale(0.98);
 }

 .trigger {
   background-color: var(--bg-tertiary);
   color: var(--text-primary);
   border: 1px solid var(--border-color);
   width: 100%;
   display: flex;
   align-items: center;
   justify-content: center;
   gap: 0.5rem;
 }

 .trigger:hover {
   background-color: var(--danger);
   border-color: var(--danger);
   color: var(--text-primary);
 }

 .btn {
   min-width: 120px;
   padding: 0.75rem 1.5rem;
 }

 .btn-secondary {
   background-color: var(--bg-tertiary);
   color: var(--text-primary);
   border: 1px solid var(--border-color);
 }

 .btn-secondary:hover {
   background-color: var(--border-color);
 }

 .btn-danger {
   background-color: var(--danger);
   color: var(--text-primary);
 }

 .btn-danger:hover {
   background-color: var(--danger-hover);
 }

 /* Dialog Styles */
 dialog {
   border: none;
   border-radius: 12px;
   background: var(--bg-secondary);
   color: var(--text-primary);
   box-shadow: 0 20px 60px rgba(0, 0, 0, 0.8);
   max-width: 420px;
   width: 90%;
   padding: 0;
 }

 dialog::backdrop {
   background-color: rgba(0, 0, 0, 0.7);
   backdrop-filter: blur(2px);
 }

 .dialog-content {
   padding: 2rem;
 }

 #delete-dialog-heading {
   font-size: 1.5rem;
   font-weight: 700;
   margin-bottom: 1rem;
   color: var(--text-primary);
 }

 .dialog-description {
   font-size: 0.95rem;
   color: var(--text-secondary);
   margin-bottom: 2rem;
   line-height: 1.6;
 }

 .dialog-actions {
   display: flex;
   gap: 1rem;
   justify-content: flex-end;
 }

 .dialog-actions .btn {
   flex: 1;
 }

 /* Responsive */
 @media (max-width: 640px) {
   body {
     padding: 1rem;
   }

   .image-library h1 {
     font-size: 1.8rem;
     margin-bottom: 1.5rem;
   }

   .gallery {
     grid-template-columns: 1fr;
     gap: 1.5rem;
   }

   dialog {
     width: 95%;
   }

   .dialog-actions {
     flex-direction: column;
   }

   .dialog-actions .btn {
     width: 100%;
   }
 }

 /* High contrast mode support */
 @media (prefers-contrast: more) {
   button:focus-visible {
     outline-width: 3px;
   }

   .image-card {
     border-width: 2px;
   }

   .trigger {
     border-width: 2px;
   }

   dialog {
     border: 2px solid var(--accent);
   }
 }

 /* Reduced motion support */
 @media (prefers-reduced-motion: reduce) {
   * {
     animation: none !important;
     transition: none !important;
   }
 }

 /* Forced colors mode (Windows High Contrast) */
 @media (forced-colors: active) {
   button,
   dialog,
   .image-card {
     border: 1px solid CanvasText;
   }

   button:focus-visible {
     outline: 2px solid Highlight;
   }

   .trigger:hover {
     background-color: Highlight;
     color: HighlightText;
   }

   dialog::backdrop {
     background-color: Canvas;
   }
 }

