 // Dialog management
 const dialog = document.getElementById('delete-dialog');
 const cancelBtn = document.getElementById('cancel-btn');
 const confirmDeleteBtn = document.getElementById('confirm-delete-btn');
 const triggers = document.querySelectorAll('.trigger');

 let currentTrigger = null;

 // Open dialog
 triggers.forEach(trigger => {
   trigger.addEventListener('click', () => {
     currentTrigger = trigger;
     dialog.showModal();
     // Focus the cancel button by default (not the destructive action)
     cancelBtn.focus();
   });
 });

 // Close dialog - Cancel button
 cancelBtn.addEventListener('click', () => {
   dialog.close('cancel');
 });

 // Close dialog - Delete button
 confirmDeleteBtn.addEventListener('click', () => {
   dialog.close('delete');
   // Find the image card and remove it with visual feedback
   if (currentTrigger) {
     const imageCard = currentTrigger.closest('.image-card');
     if (imageCard) {
       imageCard.style.opacity = '0';
       imageCard.style.transition = 'opacity 0.3s ease-out';
       setTimeout(() => {
         imageCard.remove();
         // Optional: Show success message
         console.log('Image deleted successfully');
       }, 300);
     }
   }
 });

 // Handle Escape key (automatic for native dialog, but explicit for clarity)
 dialog.addEventListener('close', () => {
   // Focus returns to trigger automatically
   if (!document.contains(currentTrigger)) {
     // Fallback: focus main if trigger no longer exists
     document.querySelector('main').focus();
   }
   currentTrigger = null;
 });

